import difflib
import json

def commit(orig_document, updated_document):
    diffs = difflib.unified_diff(orig_document.split('\n'), updated_document.split('\n'))
    diff_data = []
    for diff in diffs:
        diff_data.append(diff)

    return json.dumps(diff_data)

def revert(orig_document, diff):
    diff_data = json.loads(diff)
    i = 0
    updated_document = ""
    for line in orig_document.split('\n'):
        while i < len(diff_data):
            if diff_data[i][0] == ' ':
                updated_document += line + '\n'
                break
            elif diff_data[i][0] == '+':
                updated_document += diff_data[i][2:] + '\n'
                i += 1
                break
            else:
                i += 1
    return updated_document

