class PriorityQueueWithBST:

    def __init__(self):
        self.bst1 = {} 
        self.bst2 = {}

    def enqueue(self, value, priority):
        if priority in self.bst1:
            self.bst1[priority].append(value)
        else:
            self.bst1[priority] = [value]

        if len(self.bst2) == 0 or priority > list(self.bst2.keys())[0]: 
            if len(self.bst2) != 0:
                prev_priority = list(self.bst2.keys())[0]
                self.bst2[priority] = self.bst2[prev_priority]
                del self.bst2[prev_priority]
            else:
                self.bst2[priority] = len(self.bst1[priority])

    def dequeue(self):
        if len(self.bst2) != 0:
            priority = list(self.bst2.keys())[0]
            value = self.bst1[priority].pop(0)
            self.bst2[priority] -= 1
            if self.bst2[priority] == 0:
                del self.bst2[priority]
                if len(self.bst1) != 0:
                    next_priority = max(self.bst1.keys())
                    self.bst2[next_priority] = len(self.bst1[next_priority])
            return value
        else:
            return None

    def peek(self):
        if len(self.bst2) != 0:
            priority = list(self.bst2.keys())[0]
            return self.bst1[priority][0]
        else:
