import numpy as np

class TicTacToe:

    def __init__(self):
        self.state = '         '
        self.player = 'X'
        self.opponent = 'O'
        self.empty = ' '
        self.actions = {i: j for i, j in enumerate(self.state) if j == self.empty}
        self.reward = {'win': 1, 'draw': 0.5, 'lose': -1}

    def getState(self):
        return self.state

    def setAction(self, a):
        if a not in self.actions.keys():
            raise Exception('Invalid action')

        self.state = self.state[:a] + self.player + self.state[a+1:]

        # Switch active player
        self.player, self.opponent = self.opponent, self.player
        self.updateActions()

    def gameEnded(self):
        lines = [self.state[i:i+3] for i in range(0, 9, 3)] + \
                [self.state[i:i+9:3] for i in range(3)] + \
                [self.state[i:i+5:2] for i in (0, 2)]

        if any(line == self.player*3 for line in lines):
            return self.reward['lose'] if self.player == 'X' else self.reward['win']
        elif self.empty not in self.state:
            return self.reward['draw']
        else:
            return False

    def updateActions(self):
        self.actions = {i: j for i, j in enumerate(self.state) if j == self.empty}

    def printState(self):
        print(self.state[:3] + "\n" + self.state[3:6] + "\n" + self.state[6:])


class QLearning:

    def __init__(self, learning_rate=0.5, discount_factor=0.9, exploration_rate=1.0, iterations=10000):
        self.learning_rate = learning_rate
        self.discount_factor = discount_factor
        self.exploration_rate = exploration_rate
        self.exploration_decay = exploration_rate / iterations
        self.q_table = {}

    def q(self, gameState):
        # If the game state has not been encountered before, create an entry in the q_table
        if gameState not in self.q_table:
            self.q_table[gameState] = {i: 0 for i in TicTacToe().actions.keys()}

        return self.q_table[gameState]

    def updateQTableFromReward(self, oldGameState, action, reward, newGameState):
        self.q_table[oldGameState][action] = self.q_table[oldGameState][action] + self.learning_rate * (reward + self.discount_factor * max(self.q(newGameState).values()) - self.q_table[oldGameState][action])

    def chooseAction(self, gameState, availableActions):
        if np.random.uniform(0, 1) < self.exploration_rate:
            action = np.random.choice(list(availableActions.keys()))
        else:
            q_values = self.q(gameState)
            action = max(availableActions.keys(), key=lambda x: q_values[x])

        return action

    def updateExploration(self):
        self.exploration_rate -= self.exploration_decay


