def solve_sudoku(board):
  # Initialize empty list to store positions to be filled
  empty_positions = []

  # Iterate over board positions
  for i in range(9):
    for j in range(9):
      # Check for empty positions
      if board[i][j] == 0:
        empty_positions.append((i, j))

  # Iterate over empty positions
  for i, j in empty_positions:
    # Check if number can be placed in empty position
    for num in range(1, 10):
      if is_valid(board, num, (i, j)):
        board[i][j] = num
        if solve_sudoku(board):
          return True
        board[i][j] = 0

  return False

def is_valid(board, num, pos):
  # Check row
  for i in range(9):
    if board[pos[0]][i] == num and pos[1] != i:
      return False

  # Check column
  for i in range(9):
    if board[i][pos[1]] == num and pos[0] != i:
      return False

  # Check box
  box_x = pos[1] // 3
  box_y = pos[0] // 3

  for i in range(box_y*3, box_y*3+3):
    for j in range(box_x*3, box_x*3+3):
      if board[i][j] == num and (i, j) != pos:
        return False

  return True

