def knapsack_heuristic(items, max_weight):
    items_remaining = items
    knapsack = []
    current_weight = 0

    while items_remaining:
        max_weight_itm = 0
        max_weight_itm_weight = 0
        max_weight_itm_value = 0
        if current_weight + items_remaining[0][1] <= max_weight:
            for itm in items_remaining:
                if itm[1] > max_weight_itm_weight and (current_weight + itm[1]) <= max_weight:
                    max_weight_itm = itm
                    max_weight_itm_weight = max_weight_itm[1]
                    max_weight_itm_value = max_weight_itm[0]
        if max_weight_itm:
            knapsack.append(max_weight_itm)
            current_weight += max_weight_itm_weight
            items_remaining.remove(max_weight_itm)
        else:
            break

    return list(map(lambda x: x[0], knapsack)), sum(map(lambda x: x[0], knapsack))

