def countNodes(root):
    if not root:
        return 0

    leftdepth, rightdepth = getdepth(root.left), getdepth(root.right)

    # left is perfect tree
    # Above Height - 1's left node is a full btree, so it's amount = 2^(h-1) - 1 
    if leftdepth == rightdepth:
        return pow(2, leftdepth) + countNodes(root.right)
    else:
        # right is perfect tree
        # Above Height - 1's right node is a full btree, so it's amount = 2^(h-1) - 1
        return pow(2, rightdepth) + countNodes(root.left)

def getdepth(root):
    d = 0
    while root:
        d += 1
        root = root.left
    return d

