def reversePolishNotationCalculator(expression):
    expression_list = expression.split()
    stack = []

    for element in expression_list:
        if element in "+-*/":
            operand_1 = stack.pop()
            operand_2 = stack.pop()

            if element == "+":
                result = operand_2 + operand_1
                stack.append(result)
            elif element == "-":
                result = operand_2 - operand_1
                stack.append(result)
            elif element == "/":
                result = operand_2 / operand_1
                stack.append(result)
            else:
                result = operand_2 * operand_1
                stack.append(result)
        else:
            stack.append(int(element))

    return stack.pop()

