# Import the necessary libraries and helper functions
from random import randint
import numpy as np

def gen_population(pop_size):
    """Generate a population of random 3x3 grids of colours"""
    population = []
    for _ in range(pop_size):
        grid = np.random.randint(low=0, high=15, size=(3,3))
        population.append(grid)
    return population

def fitness(grid):
    """Calculate the fitness of a grid by summing the number of same colours in adjacent cells"""
    score = 0
    for r in range(grid.shape[0]):
        for c in range(grid.shape[1]):
            if r < grid.shape[0] - 1:
                if grid[r, c] == grid[r+1, c]:
                    score += 1
            if c < grid.shape[1] - 1:
                if grid[r, c] == grid[r, c+1]:
                    score += 1
    return score

def selection(population, fitness):
    """Choose two parents from the population depending on their fitnesses"""
    parents = []
    while len(parents) < 2:
        ix = randint(0, len(population)-1)
        if fitness[ix] > 0:
            parents.append(population.pop(ix))
            fitness.pop(ix)
    return parents

def crossover(parents):
    """Perform genetic crossover by combining the parts of the two parents"""
    crossover_point = randint(0, 2)
    child1 = np.concatenate([parents[0][:crossover_point+1], 
                             parents[1][crossover_point+1:]], axis=1).flatten()
    child2 = np.concatenate([parents[1][:crossover_point+1], 
                             parents[0][crossover_point+1:]], axis=1).flatten()
    return (child1.reshape(3,3), child2.reshape(3,3))

