def minJumps(arr): 
    n = len(arr) 

    # Create a jumps array to store the number of jumps needed to reach the end from the starting point 
    jumps = [float('inf') for i in range(n)] 

    # If the first element is 0, then it can't reach the key 
    if arr[0] == 0: 
        return float('inf') 

    # From the starting position, traverse to the right, updating the minimum jumps needed in the jumps array element 
    jumps[0] = 0
    for i in range(1, n): 
        for j in range(i): 
            if i <= j + arr[j] and jumps[j] != float('inf'): 
                jumps[i] = min(jumps[i], jumps[j] + 1) 
                break
    return jumps[n-1]

