import hashlib as hasher

class Block:
    def __init__(self, data, previous_hash):
        self.data = data
        self.previous_hash = previous_hash
        self.hash = self.calc_hash()

    def calc_hash(self):
        sha = hasher.sha256()
        hash_str = (self.data + str(self.previous_hash)).encode('utf-8')
        sha.update(hash_str)
        return sha.hexdigest()

class VotingSystem:
    def __init__(self, candidate_name_list):
        self.blockchain = [self.create_genesis_block()]
        self.candidates = candidate_name_list
        self.votes = {candidate: 0 for candidate in candidate_name_list}

    def create_genesis_block(self):
        return Block('Genesis Block', '0')

    def add_block(self, data):
        last_block = self.blockchain[-1]
        new_block = Block(data, last_block.hash)
        self.blockchain.append(new_block)

    def find_winner(self):
        winner_candidate = max(self.votes, key=self.votes.get)
        return winner_candidate

    def cast_vote(self, candidate_name):
        self.votes[candidate_name] += 1 
        self.add_block(candidate_name)

