def binary_search(list, item):
    low = 0
    high = len(list) - 1

    while low <= high:
        mid = (low + high) // 2
        guess = list[mid]

        if guess == item:
            left = mid - 1
            while left >= 0 and list[left] == item:
                left -= 1

            if left >= 0 and list[left] == item:
                return left

            return mid

        if guess > item:
            high = mid - 1
        else:
            low = mid + 1

    return None

