		self.array.append(op) 

	# A utility function to check if the given character is an operand 
	def isOperand(self, ch): 
		return ch.isalpha() 

	# Check if the precedence of an operator is strictly less than top of stack or not 
	def notGreater(self, i): 
		try: 
			a = self.precedence[i] 
			b = self.precedence[self.peek()] 
			return True if a <= b else False
		except KeyError: 
			return False

	# The main function that converts a given infix expression to a postfix expression 
	def infixToPostfix(self, exp): 

		# Iterate over the expression for conversion 
		for i in exp: 
			# If the character is an operand, add it to the output 
			if self.isOperand(i): 
				self.output.append(i) 

			# If the character is an '(', push it to the stack 
			elif i == '(': 
				self.push(i) 

			# If the scanned character is an ')', pop and output from the stack until '(' is found 
			elif i == ')': 
				while(not self.isEmpty() and self.peek() != '('): 
					a = self.pop() 
					self.output.append(a) 
				if not self.isEmpty() and self.peek() != '(':
					return -1
				else: 
					self.pop() 

			# An operator is encountered 
			else: 
				while(not self.isEmpty() and self.notGreater(i)): 
					self.output.append(self.pop()) 
				self.push(i) 

		# Pop all the operators from the stack 
		while not self.isEmpty(): 
			self.output.append(self.pop()) 

		print("".join(self.output))

