class TrieNode:
    # Each node in the trie contains a dictionary to hold child nodes,
    # and a boolean to mark the end of a word
    def __init__(self):
        self.children = {}
        self.isEnd = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    # Function to add a word to the trie
    def add(self, word):
        node = self.root
        for char in word:
            # If character is not in current node's children,
            # create a new TrieNode and add it to the current node's children
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        # Mark the current node as the end of a word
        node.isEnd = True

    # Function to check if a word is in the trie
    def search(self, word):
        node = self.root
        for char in word:
            # If a character in the word is not in the current node's children,
            # the word is not in the trie
            if char not in node.children:
                return False
            node = node.children[char]
        # Return whether the current node is the end of a word
        return node.isEnd

    # Function to check if a prefix is in the trie
    def startWith(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True

