def knapsack(values, weights, capacity): 

    n = len(values) 

    # table to store the intermediate results 
    # i.e. the optimal solution to subproblems 
    table = [[0 for x in range(capacity+1)] for y in range(n+1)] 

    # fill the table in bottom-up manner 
    for i in range(n+1): 
        for c in range(capacity+1): 
            if i==0 or c==0: 
                table[i][c] = 0
            elif weights[i-1] <= c: 
                table[i][c] = max(values[i-1] + table[i-1][c-weights[i-1]], table[i-1][c]) 
            else: 
                table[i][c] = table[i-1][c] 

    maxWeight=table[n][capacity] 

    items=[] 
    c= capacity 
    for i in range(n, 0, -1): 
        if maxWeight <= 0: 
            break
        if maxWeight == table[i - 1][c]:
            continue
        else: 
            items.append(i-1) 
            maxWeight = maxWeight - values[i - 1]
            c= c - weights[i - 1] 

    return (table[n][capacity], items) 

