import numpy as np
import time

def next_generation(board):
    width = len(board[0])
    height = len(board)
    next = np.zeros((height, width), dtype = int)

    for y in range(height):
        for x in range(width):
            living_neighbors = 0
            for dy in [-1, 0, 1]:
                for dx in [-1, 0, 1]:
                    if dy == 0 and dx == 0 or x + dx < 0 or x + dx > width - 1 or y + dy < 0 or y + dy > height - 1:
                        continue
                    living_neighbors += board[y + dy][x + dx]

            if board[y][x] == 1 and living_neighbors == 2 or living_neighbors == 3:
                next[y][x] = 1
            elif board[y][x] == 0 and living_neighbors == 3:
                next[y][x] = 1
            else:
                next[y][x] = 0
    return next

def life(board):
    while True:
        board = next_generation(board)
        yield board
        time.sleep(1)

