# Defining the Queue class
class Queue:
    def __init__(self):
        self.head = None

    # To insert data in the queue
    def enqueue(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
            return
        curr_node = self.head
        while curr_node.next is not None:
            curr_node = curr_node.next
        curr_node.next = new_node

    # To delete data from the queue
    def dequeue(self):
        if self.head is None:
            return None
        prev_node = None
        curr_node = self.head
        while curr_node.next is not None:
            prev_node = curr_node
            curr_node = curr_node.next
        if prev_node is None:
            self.head = None
        else:
            prev_node.next = None
        return curr_node.data

