def postfix_evaluation(expression):
    """Evaluates a postfix expression"""
    stack = []
    for i in expression.split():
        if i.isdigit():
            stack.append(i)
        else:
            a = int(stack.pop())
            b = int(stack.pop())
            if i == '+':
                stack.append(b + a)
            elif i == '-':
                stack.append(b - a)
            elif i == '*':
                stack.append(b * a)
            elif i == '/':
                stack.append(b / a)
            elif i == '%':
                stack.append(b % a)
    return int(stack.pop())

