def encrypt(text, shift): 
  result = "" 

  for i in range(len(text)):
    char = text[i]

    if (char.isalpha()):
        char_code = ord(char)
        char_code += shift
        if char.isupper():
            if char_code > ord('Z'):
                char_code -= 26
            elif char_code < ord('A'):
                char_code += 26
        elif char.islower():
            if char_code > ord('z'):
                char_code -= 26
            elif char_code < ord('a'):
                char_code += 26
        result += chr(char_code)
    else:
        result += char

