class PriorityQueue: 
    def __init__(self): 
        self.heap = [] 

    def parent(self, i): 
        return (i-1)/2

    def insertKey(self, k): 
        self.heap.append(k) 
        i = len(self.heap) - 1
        while i != 0 and self.heap[self.parent(i)] > self.heap[i]: 
            self.heap[i], self.heap[self.parent(i)] = ( 
            self.heap[self.parent(i)], self.heap[i]) 
            i = self.parent(i) 

    def decreaseKey(self, i, new_val): 
        self.heap[i] = new_val 
        while i != 0 and self.heap[self.parent(i)] > self.heap[i]: 
            self.heap[i], self.heap[self.parent(i)] = ( 
            self.heap[self.parent(i)], self.heap[i]) 
            i = self.parent(i) 

    def extractMax(self): 
        if len(self.heap) == 0: 
            return
        if len(self.heap) == 1: 
            return self.heap.pop() 

        root = self.heap[0] 
        self.heap[0] = self.heap.pop() 
        self.maxHeapify(0) 
        return root 

    def maxHeapify(self, i): 
        l = 2*i + 1
        r = 2*i + 2
        size = len(self.heap) 
        largest = i
        if l < size and self.heap[i] < self.heap[l]: 
            largest = l 
        if r < size and self.heap[largest] < self.heap[r]: 
            largest = r 
        if largest != i: 
            self.heap[i] , self.heap[largest] = ( 
            self.heap[largest], self.heap[i])  
            self.maxHeapify(largest)

