def quick_sort(arr, first, last):
    if first < last:
        pivot_index = partition(arr, first, last)
        quick_sort(arr, first, pivot_index)
        quick_sort(arr, pivot_index + 1, last)


def get_pivot(arr, first, last):
    mid = (last + first) // 2
    pivot = max(min(arr[first], arr[mid]), min(max(arr[first], arr[mid]), arr[last]))
    return arr.index(pivot)


def partition(arr, first, last):
    pivot_index = get_pivot(arr, first, last)
    arr[first], arr[pivot_index] = arr[pivot_index], arr[first]
    pivot = arr[first]
    i = first + 1
    j = last

    while True:
        while i <= j and arr[i] <= pivot:
            i += 1
        while i <= j and arr[j] >= pivot:
            j -= 1
        if i <= j:
            arr[i], arr[j] = arr[j], arr[i]
        else:
            arr[first], arr[j] = arr[j], arr[first]
            return j


def optimized_quicksort(arr):
    quick_sort(arr, 0, len(arr) - 1)
    return arr

