import heapq

def huffman_encoding(data):
    frequencies = {}
    for char in data:
        if char not in frequencies:
            frequencies[char] = 0
        frequencies[char] += 1

    heap = [[freq, [char, '']] for char, freq in frequencies.items()]
    heapq.heapify(heap)

    while len(heap) > 1:
        left = heapq.heappop(heap)
        right = heapq.heappop(heap)

        for pair in left[1:]:
            pair[1] = '0' + pair[1]
        for pair in right[1:]:
            pair[1] = '1' + pair[1]
        heapq.heappush(heap, [left[0] + right[0]] + left[1:] + right[1:])

    codes = {}
    for freq, code in heapq.heappop(heap)[1:]:
        codes[code] = freq

    return codes

