class ConnectFourGame():
    def __init__(self, player="X", size=6):
        self.turn = player
        self.board = np.zeros((size, size), dtype=str)
        self.columns = []

    def play(self, col):
        if not 0 <= col < 7 or col in self.columns:
            return

        if self.turn == "X":
            self.board[:, col][self.board[:, col] == 0] = "X"
            self.turn = "O"
            self.columns.append(col)
        else:
            self.board[:, col][self.board[:, col] == 0] = "O"
            self.turn = "X"
            self.columns.append(col)

