        last_player = ""
        if self.turn == "X":
            last_player = "O"
        else:
            last_player = "X"

        # vertical check
        for i in range(7):
            for j in range(3):
                if np.all(self.board[j:j+4, i] == last_player):
                    return True

        # horizontal check
        for i in range(6):
            for j in range(4):
                if np.all(self.board[i, j:j+4] == last_player):
                    return True

        # diagonal check
        for i in range(3):
            for j in range(4):
                if (np.all(self.board[i:i+4, j:j+4].diagonal() == last_player) or
                        np.all(np.fliplr(self.board[i:i+4, j:j+4]).diagonal() == last_player)):
