        left = (2 * index) + 1 
        right = (2 * index) + 2 
        smallest = index 
        if len(self.heap) > left and self.heap[smallest] > self.heap[left]: 
            smallest = left 
        if len(self.heap) > right and self.heap[smallest] > self.heap[right]: 
            smallest = right

        if smallest != index: 
            self.swap(index, smallest) 
            self.perc_down(smallest) 

