class Quaternion:
    def __init__(self, w=0, x=0, y=0, z=0):
        self.w = w
        self.x = x
        self.y = y
        self.z = z

    def __repr__(self):
        return f"{self.w} + {self.x}i + {self.y}j + {self.z}k"

    def __add__(self, other):
        return Quaternion(
            self.w + other.w,
            self.x + other.x,
            self.y + other.y,
            self.z + other.z,
        )

    def __sub__(self, other):
        return Quaternion(
            self.w - other.w,
            self.x - other.x,
            self.y - other.y,
            self.z - other.z,
        )

    def __mul__(self, other):
        w = self.w * other.w - self.x * other.x - self.y * other.y - self.z * other.z
        x = self.w * other.x + self.x * other.w + self.y * other.z - self.z * other.y
        y = self.w * other.y - self.x * other.z + self.y * other.w + self.z * other.x
        z = self.w * other.z + self.x * other.y - self.y * other.x + self.z * other.w
        return Quaternion(w, x, y, z)

    def __truediv__(self, other):
        other_conjugate = Quaternion(other.w, -other.x, -other.y, -other.z)
        numerator = self * other_conjugate
        denominator = other * other_conjugate

        if denominator.w == 0:
            raise ZeroDivisionError("division by zero quaternion")

        return Quaternion(
            numerator.w / denominator.w,
            numerator.x / denominator.w,
            numerator.y / denominator.w,
            numerator.z / denominator.w,
        )

    def conjugate(self):
        return Quaternion(self.w, -self.x, -self.y, -self.z)

    def norm(self):
        return (self.w ** 2 + self.x ** 2 + self.y ** 2 + self.z ** 2) ** 0.5

    def normalize(self):
        norm = self.norm()
        return Quaternion(self.w / norm, self.x / norm, self.y / norm, self.z / norm)


