def solve_sudoku(board):
    # initialise a 'solved' flag, if true = solved, if false = not solved    
    solved = False

    for row in range(0, 9):
        for col in range(0, 9):
            if board[row][col] == 0:

                # Generate a list of all possible numbers for the current grid cell
                possibleNumbers = [1, 2, 3, 4, 5, 6, 7, 8, 9]

                # Remove already existing numbers in the current row
                for r in range(0, 9):
                    if board[r][col] in possibleNumbers:
                        possibleNumbers.remove(board[r][col])

                # Remove already existing numbers in the current column
                for c in range(0, 9):
                    if board[row][c] in possibleNumbers:
                        possibleNumbers.remove(board[row][c])

                # Remove already existing numbers in the current 3x3 block
                # Find which block the current cell belongs to
                blockRow = row // 3    #Integer division
                blockCol = col // 3    #Integer division

                for r in range(blockRow * 3, blockRow * 3 + 3):
                    for c in range(blockCol * 3, blockCol * 3 + 3):
                        if board[r][c] in possibleNumbers:
                            possibleNumbers.remove(board[r][c])

                if len(possibleNumbers) == 0: 
                    # 'Backtrack' if the possible numbers list is empty

                    # Set the 'solved' flag to false and return to the last good state
                    solved = False
                    return 

                else:
                    # Here we have some possible numbers so we assign them to the current grid cell and 'recurse'
                    for number in possibleNumbers:
                        board[row][col] = number
                        solved = solve_sudoku(board)

                        if solved is True:
                            return True

    # If we have been through all cells, the sudoku is solved
    solved = True
    return solved

