def merge_sort(data):
    if len(data) <= 1:
        return data

    middle = len(data) // 2
    left_data = data[:middle]
    right_data = data[middle:]

    left_data = merge_sort(left_data)
    right_data = merge_sort(right_data)
    return merge(left_data, right_data)

def merge(left_data, right_data):
    sorted_array = []
    left_data_index = right_data_index = 0

    while left_data_index < len(left_data) and right_data_index < len(right_data):
        if left_data[left_data_index] <= right_data[right_data_index]:
            sorted_array.append(left_data[left_data_index])
            left_data_index += 1
        else:
            sorted_array.append(right_data[right_data_index])
            right_data_index += 1

    if len(left_data[left_data_index:]) > 0:
        sorted_array += left_data[left_data_index:]

    if len(right_data[right_data_index:]) > 0:
        sorted_array += right_data[right_data_index:]

    return sorted_array

