import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def normalize_array(arr):
    total_sum = sum(arr)
    if is_prime(total_sum):
        return arr

    while True:
        next_prime = total_sum + 1
        while not is_prime(next_prime):
            next_prime += 1

        diff = next_prime - total_sum
        quotient = diff // len(arr)
        remainder = diff % len(arr)

        for i in range(len(arr)):
            arr[i] += quotient
            if remainder > 0:
                arr[i] += 1
                remainder -= 1

        total_sum = sum(arr)
        if is_prime(total_sum):
            return arr

