class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BalancedTernarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_helper(self.root, value)

    def _insert_helper(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert_helper(node.left, value)
        elif value > node.value:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_helper(node.right, value)
        else:
            return

    def search(self, value):
        return self._search_helper(self.root, value)

    def _search_helper(self, node, value):
        if node is None or node.value == value:
            return node
        if value < node.value:
            return self._search_helper(node.left, value)
        return self._search_helper(node.right, value)

    def delete(self, value):
        self.root = self._delete_helper(self.root, value)

    def _delete_helper(self, node, value):
        if node is None:
            return node
        if value < node.value:
            node.left = self._delete_helper(node.left, value)
        elif value > node.value:
            node.right = self._delete_helper(node.right, value)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left
            min_value = self._find_min(node.right)
            node.value = min_value
            node.right = self._delete_helper(node.right, min_value)
        return node

    def _find_min(self, node):
        while node.left is not None:
            node = node.left
        return node.value

    def print_tree(self):
        self._print_tree_helper(self.root)

    def _print_tree_helper(self, node):
        if node is not None:
            self._print_tree_helper(node.left)
            print(node.value, end=' ')
            self._print_tree_helper(node.right)

