from multiprocessing import Process

def count_primes(n):
    primes = [True] * n
    for p in range(3, int(n**0.5)+1, 2):
        if primes[p]:
            primes[p*2::p] = [False] * ((n - p*2 - 1) // p + 1)
    return primes[2:].count(True)

def count_primes_in_range(primes, low, high):
    result = 0
    for i in primes[low:high]:
        if i:
            result += 1
    return result

def count_primes_parallel(n):
    primes = [True] * n
    processes = []
    result = 0
    for p in range(3, int(n**0.5)+1, 2):
        if primes[p]:
            primes[p*2::p] = [False] * ((n - p*2 - 1) // p + 1)
            # Spin off separate process to work on a slice of primes
            processes.append(Process(target = count_primes_in_range, args = (primes, p, n, )))
            processes[-1].start()

    # Join all processes and aggregate results
    for process in processes:
        result += process.join()

    return result

