import operator, math
import re

class Parser:
    def __init__(self, string):
        self.tokens = re.findall("\d+|\+|\-|\*|\/|\(|\)| ", string)
        self.tokens = [token for token in self.tokens if token != ' ']
        self.index = 0

    def parse(self):
        return self.expression()

    def consume(self, token):
        if self.tokens[self.index] == token:
            self.index += 1
        else:
            raise ValueError("Incorrect syntax")

    def expression(self):
        value = self.term()

        while self.index < len(self.tokens) and self.tokens[self.index] in ['+', '-']:
            if self.tokens[self.index] == '+':
                self.consume('+')
                value += self.term()
            elif self.tokens[self.index] == '-':
                self.consume('-')
                value -= self.term()

        return value

    def term(self):
        value = self.factor()

        while self.index < len(self.tokens) and self.tokens[self.index] in ['*', '/']:
            if self.tokens[self.index] == '*':
                self.consume('*')
                value *= self.factor()
            elif self.tokens[self.index] == '/':
                self.consume('/')
                value /= self.factor()

        return value

    def factor(self):
        if self.tokens[self.index].isdigit():
            value = int(self.tokens[self.index])
            self.consume(self.tokens[self.index])
        elif self.tokens[self.index] == '(':
            self.consume('(')
            value = self.expression()
            self.consume(')')

        return value    

def evaluate(expression):
    parser = Parser(expression)
    result = parser.parse()

    print(f"Result of '{expression}' is '{result}'")

evaluate("5+(3*2)")
evaluate("4/(2-1)")


