def a_star(start_node, end_node, graph):
    closed_nodes = []
    open_nodes = [start_node]
    g_scores = {start_node : 0}
    h_scores = {start_node : 0}
    predecessors = {}

    while open_nodes:
        current_node = None
        for node in open_nodes: 
            if node not in g_scores or g_scores[node] < g_scores[current_node]:
                current_node = node
        if current_node == end_node:
            path = [current_node]
            while current_node in predecessors:
                current_node = predecessors[current_node]
                path.append(current_node)
            path.reverse()
            return path

        open_nodes.remove(current_node)
        closed_nodes.append(current_node)
        for node, cost in graph[current_node].items():
            if node not in closed_nodes:
                if node in open_nodes:
                    new_cost = g_scores[current_node] + cost
                    if g_scores[node] > new_cost:
                        g_scores[node] = new_cost
                        predecessors[node] = current_node
                else:
                    g_scores[node] = g_scores[current_node] + cost
                    h_scores[node] = cost
                    open_nodes.append(node)
                    predecessors[node] = current_node

    return None

