def find_path(maze, start, end):
    rows = len(maze)
    cols = len(maze[0])

    def is_valid_move(row, col):
        return 0 <= row < rows and 0 <= col < cols and maze[row][col] != '#'

    def backtrack(row, col):
        if (row, col) == end:
            return True

        if is_valid_move(row, col):
            maze[row][col] = '#'  # Mark as visited

            # Try moving up, down, left, and right
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                if backtrack(row + dr, col + dc):
                    return True

            maze[row][col] = '.'  # Mark as unvisited (backtracking)

        return False

    if backtrack(start[0], start[1]):
        print("A path from start to end exists.")
    else:
        print("No path exists.")

