class Node:
    def __init__(self, value):
        self.data = value
        self.left = None
        self.right = None

def _insert(root, value):
    if not root:
        return Node(value)

    elif root.data > value:
        root.left = _insert(root.left, value)
    elif root.data < value:
        root.right = _insert(root.right, value)

    return root

def construct_expression_tree(postfix):
    stack = []
    for char in postfix:
        if char.isalpha():
            stack.append(Node(char))
        elif char in ['+', '-', '*', '/']:
            temp = Node(char)
            temp.right = stack.pop()
            temp.left = stack.pop()
            stack.append(temp)
    return stack[0]

