def infixToPostfix(infix):
    operators = ["+", "-", "*", "/"]
    postfix = []
    opStack = []

    for token in infix:
        tok = str(token)

        if tok not in operators:
            postfix.append(tok)
        else:
            while len(opStack) != 0 and opStack[-1] != "(":
                if precedence(token) > precedence(opStack[-1]):
                    postfix.append(opStack.pop())
                else:
                    break
            opStack.append(tok)

    while len(opStack) != 0:
        postfix.append(opStack.pop())

    return postfix

def precedence(token):
    prec = {
        "+": 1,
        "-": 1,
        "*": 2,
        "/": 2
    }
    return prec[token]

