def is_anagram(word1, word2):
    # Check if both words are the same size
    if len(word1) != len(word2):
        return False

    # Create a dictionary to store the number of characters in each word
    word_dict = {}

    # Populate the dictionary with characters from each word
    for char in word1:
        if char in word_dict.keys():
            word_dict[char] += 1
        else:
            word_dict[char] = 1

    # Decrement the characters for each word
    for char in word2:
        if char in word_dict.keys():
            word_dict[char] -= 1
        else:
            return False

    # Check if all values in the dictionary are zero
    for value in word_dict.values():
        if value != 0:
            return False

    return True

