class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.usage = []

    def get(self, key):
        if key in self.cache:
            self.usage.remove(key)  # Remove the key from usage list
            self.usage.append(key)  # Add it to the end to denote recent usage
            return self.cache[key]
        else:
            return None

    def set(self, key, value):
        if key in self.cache:
            self.usage.remove(key)  # Remove the key from usage list
        elif len(self.cache) >= self.capacity:
            evicted_key = self.usage.pop(0)  # Remove the least recently used key from usage list
            del self.cache[evicted_key]  # Remove it from cache
        self.cache[key] = value
        self.usage.append(key)  # Add the key to the end of usage list

