def binary_search_rotated(arr, target):
    lo = 0
    hi = len(arr) - 1

    while lo <= hi:
        mid = (lo + hi)//2
        if target == arr[mid]:
            return mid
        elif arr[lo] <= arr[mid]:
            if target >= arr[lo] and target < arr[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if target > arr[mid] and target <= arr[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

