def matrixMultiplication(A, B):
    # Get the dimensions of the matrices
    rows_A = len(A)
    cols_A = len(A[0])
    rows_B = len(B)
    cols_B = len(B[0])

    # Check if the matrices can be multiplied
    if cols_A != rows_B:
        print("Cannot multiply the two matrices. Incorrect dimensions.")
        return

    # Create the result matrix
    # Dimensions would be rows_A x cols_B
    C = [[0 for row in range(cols_B)] for col in range(rows_A)]

    # If matrices are small enough, use traditional matrix multiplication
    if rows_A <= 2 or cols_A <= 2 or cols_B <= 2:
        for i in range(rows_A):
            for j in range(cols_B):
                for k in range(cols_A):
                    C[i][j] += A[i][k] * B[k][j]
    else:
        # Divide the matrices into submatrices
        mid = rows_A // 2

        A11 = [[0 for col in range(mid)] for row in range(mid)]
        A12 = [[0 for col in range(cols_A - mid)] for row in range(mid)]
        A21 = [[0 for col in range(mid)] for row in range(rows_A - mid)]
        A22 = [[0 for col in range(cols_A - mid)] for row in range(rows_A - mid)]

        B11 = [[0 for col in range(mid)] for row in range(mid)]
        B12 = [[0 for col in range(cols_B - mid)] for row in range(mid)]
        B21 = [[0 for col in range(mid)] for row in range(rows_B - mid)]
        B22 = [[0 for col in range(cols_B - mid)] for row in range(rows_B - mid)]

        C11 = [[0 for col in range(mid)] for row in range(mid)]
        C12 = [[0 for col in range(cols_B - mid)] for row in range(mid)]
        C21 = [[0 for col in range(mid)] for row in range(rows_A - mid)]
        C22 = [[0 for col in range(cols_B - mid)] for row in range(rows_A - mid)]

        # Populate the submatrices
        for i in range(mid):
            for j in range(mid):
                A11[i][j] = A[i][j]
                B11[i][j] = B[i][j]

        for i in range(mid):
            for j in range(mid, cols_A):
                A12[i][j - mid] = A[i][j]
                B12[i][j - mid] = B[i][j]

        for i in range(mid, rows_A):
            for j in range(mid):
                A21[i - mid][j] = A[i][j]
                B21[i - mid][j] = B[i][j]

        for i in range(mid, rows_A):
            for j in range(mid, cols_A):
                A22[i - mid][j - mid] = A[i][j]
                B22[i - mid][j - mid] = B[i][j]

        # Recursive calls for matrix multiplication
        C11 = matrixMultiplication(A11, B11) + matrixMultiplication(A12, B21)
        C12 = matrixMultiplication(A11, B12) + matrixMultiplication(A12, B22)
        C21 = matrixMultiplication(A21, B11) + matrixMultiplication(A22, B21)
        C22 = matrixMultiplication(A21, B12) + matrixMultiplication(A22, B22)

        # Combine the submatrices to get the result matrix
        for i in range(mid):
            for j in range(mid):
                C[i][j] = C11[i][j]

        for i in range(mid):
            for j in range(mid, cols_B):
