def longest_palindrome(s):
    max_len = 0
    curr_len = 0

    for i in range(len(s)):
        curr_len = findPalindrome(s, i, i + 1)
        if curr_len > max_len:
            max_len = curr_len

    for i in range(len(s) - 1):
        curr_len = findPalindrome(s, i, i + 2)
        if curr_len > max_len:
            max_len = curr_len

    return max_len

def findPalindrome(s, left, right):
    while left >= 0 and right < len(s) and s[left] == s[right]:
        left -= 1
        right += 1
    return right - left - 1

