def parse_expression(grammar, index):
    left = parse_term(grammar, index)

    if left:
        if index + 1 < len(grammar) and grammar[index + 1] == '+':
            node = Node('+')
            node.children.append(left)
            node.children.append(parse_expression(grammar, index + 2))
            return node
        elif index + 1 < len(grammar) and grammar[index + 1] == '*':
            node = Node('*')
            node.children.append(left)
            node.children.append(parse_expression(grammar, index + 2))
            return node
        else:
            return left

def parse_term(grammar, index):
    if grammar[index] == '(':
        node = parse_expression(grammar, index + 1)
        if node and index + 2 < len(grammar) and grammar[index + 2] == ')':
            return node
    elif grammar[index].isalpha():
        return Node(grammar[index])

    return None

