    if len(str1) != len(str2):
        return False

    # Create a dictionary to store the frequency of each letter
    freq_dict = {}

    # Calculate the frequency of each letter in the first string and store it in the dictionary
    for letter in str1:
        if letter in freq_dict:
            freq_dict[letter] += 1
        else:
            freq_dict[letter] = 1

    # Check if the frequency of each letter in the second string is present in the dictionary
    for letter in str2:
        if letter not in freq_dict:
            return False
        else:
            freq_dict[letter] -= 1

    # Check if each letter in the dictionary has a frequency of zero
    for letter in freq_dict:
        if freq_dict[letter] != 0:
            return False

    return True

