def one_edit_away(s1, s2):
    len_diff = abs(len(s1) - len(s2))
    # if difference in lengths is greater than 1, return False
    if len_diff > 1:
        return False
    elif len_diff == 0:
        # if strings are of the same length, check for replacement
        replacement_found = False
        for c1, c2 in zip(s1, s2):
            if c1 != c2:
                if replacement_found:
                    return False
                replacement_found = True
        return True
    else:
        # if strings have different lengths, check for insertion
        if len(s1) > len(s2):
            s1, s2 = s2, s1
        insertion_found = False
        i = j = 0
        while i < len(s1) and j < len(s2):
            if s1[i] != s2[j]:
                if insertion_found:
                    return False
                insertion_found = True
                j += 1
            else:
                i += 1
                j += 1
        return True

