def minEditDistance(word1, word2): 
    m = len(word1)+1
    n = len(word2)+1

    dp_table = [[0 for i in range(n)] for j in range(m)] 

    for i in range(m): 
        dp_table[i][0] = i 

    for j in range(n): 
        dp_table[0][j] = j 

    for i in range(1, m): 
        for j in range(1, n): 
            if word1[i-1] == word2[j-1]: 
                dp_table[i][j] = dp_table[i-1][j-1] 

            else: 
                dp_table[i][j] = 1 + min(dp_table[i][j-1], 
                                    dp_table[i-1][j],  
                                    dp_table[i-1][j-1])
    return dp_table[m-1][n-1]

