def solve_sudoku(board):
  # use a recursive algorithm
  if is_complete(board):
    return board
  row, col = next_cell(board)
  for n in range(1, 10):
    if safe(board, row, col, n):
      board[row][col] = n
      result = solve_sudoku(board)
      if result:
         return result
      board[row][col] = 0 
  return False

def is_complete(board):
  for row in board:
    for col in row:
      if col == 0:
        return False
  return True

def next_cell(board):
  for row_index, row in enumerate(board):
    for col_index, col in enumerate(row):
      if col == 0:
        return (row_index, col_index)

def safe(board, row, col, n):
  return verify_row(board, row, n) and verify_column(board, col, n) and verify_squares(board, row, col, n)

def verify_row(board, row, n):
  if n in board[row]:
    return False
  return True

def verify_column(board, col, n):
  for row in board:
    if n == row[col]:
      return False
  return True

def verify_squares(board, row, col, n):
  cell_row = row//3
  cell_col = col//3
  for i in range(cell_row * 3, cell_row * 3 + 3):
    for j in range(cell_col * 3, cell_col * 3 + 3):
      if board[i][j] == n:
        return False
  return True

