def max_flow(graph, source, sink):
    # Initialize flow with 0's
    flow = {}
    for i in graph:
        flow[i] = {}
        for j in graph[i]:
            flow[i][j] = 0

    # Augment the flow while there is a path from source to sink
    while bfs(graph, source, sink, flow):
        # Find residual capacities for each edge
        path_flow, parent = bfs(graph, source, sink, flow)

        # Find the minimum of residual capacities for all edges
        min_flow = min(path_flow)

        # Add the min_flow to each edge along the path
        v = sink
        while v != source:
            u = parent[v]
            flow[u][v] += min_flow
            flow[v][u] -= min_flow
            v = parent[v]

    # Check if the network has been fully saturated
    totalflow = 0
    for i in graph[source]:
        totalflow += flow[source][i]

    return (totalflow, flow)

