def knapsack(values, weights, W):
    n = len(values)
    dp = [[0] * (W + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(1, W + 1):
            if weights[i - 1] <= w and values[i - 1] + dp[i - 1][w - weights[i - 1]] > dp[i - 1][w]:
                dp[i][w] = values[i - 1] + dp[i - 1][w - weights[i - 1]]
            else:
                dp[i][w] = dp[i - 1][w]

    return dp[n][W]

