def bin_packing(items, bin_size):
    # First fit
    bins = []
    for item in items:
        placed = False
        for b in bins:
            if b + item <= bin_size:
                b += item
                placed = True

        if not placed:
            bins.append(item)

    # Next fit
    optimised_bins = []
    for item in items:
        placed = False
        for b in optimised_bins:
            if b + item <= bin_size:
                optimised_bins.append((b, b + item))
                placed = True
                break

        if not placed:
            optimised_bins.append((item, item))

    return bins, optimised_bins

