class MaxHeap:
  def __init__(self, arr = []):
    self.heap = arr

  def get_parent_index(self, i):
      return i // 2

  def get_left_child_index(self, i):
    return 2 * i

  def get_right_child_index(self, i):
    return 2 * i + 1

  def has_parent(self, i):
    return self.get_parent_index(i) >= 0

  def has_left_child(self, i):
    return self.get_left_child_index(i) < len(self.heap)

  def has_right_child(self, i):
    return self.get_right_child_index(i) < len(self.heap)

  def get_parent(self, i):
    return self.heap[self.get_parent_index(i)]

  def get_left_child(self, i):
    return self.heap[self.get_left_child_index(i)]

  def get_right_child(self, i):
    return self.heap[self.get_right_child_index(i)]

  def swap(self, i, j):
    self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

  def heapify_up(self):
    index = len(self.heap) - 1

    while self.has_parent(index) and self.get_parent(index) < self.heap[index]:
      self.swap(self.get_parent_index(index), index)
      index = self.get_parent_index(index)

  def heapify_down(self):
    index = 0

    while self.has_left_child(index):

      larger_child_index = self.get_left_child_index(index)

      if self.has_right_child(index) and self.get_right_child(index) > self.get_left_child(index):
        larger_child_index = self.get_right_child_index(index)

      if self.heap[index] > self.heap[larger_child_index]:
        break
      else:
        self.swap(index, larger_child_index)
        index = larger_child_index

  def insert(self, elem):
    self.heap.append(elem)
    self.heapify_up()

  def get_max(self):
      return self.heap[0]

  def extract_max(self):
    max_elem = self.heap[0]
