def knapsack(items, maxWeight):
    matrix = [[0 for i in range(maxWeight+1)] for j in range(len(items)+1)]

    for i in range(1, len(items)+1):
        for w in range(1, maxWeight+1):
            if items[i-1][1] <= w:
                matrix[i][w] = max(items[i-1][0] + matrix[i-1][w-items[i-1][1]],  matrix[i-1][w])
            else:
                matrix[i][w] = matrix[i-1][w]
    return matrix[len(items)][maxWeight]

