class HashTable:
    def __init__(self):
        self.table = []

    def hash_string(self, key):
        # Hashfunction algorithm
        hashed_value = 0
        for character in key:
            hashed_value += ord(character)
        return hashed_value % 256

    def put(self, key, value):
        key_hash = self.hash_string(key)
        key_value = [key, value]

        # Check if hashed value is already present
        if self.table[key_hash] is None:
            self.table[key_hash] = list([key_value])
            return True
        else:
            for pair in self.table[key_hash]:
                if pair[0] == key:
                    pair[1] = value
                    return True

            self.table[key_hash].append(key_value)
            return True

    def get(self, key):
        key_hash = self.hash_string(key)

        # Check if the hashed value is present
        if self.table[key_hash] is not None:
            for pair in self.table[key_hash]:
                if pair[0] == key:
                    return pair[1]
        return None

