import random

def gen_puzzle(n):
    """Generates a random nxn puzzle"""
    board = [[0 for i in range(n)] for j in range(n)]

    for x in range(n):
        for y in range(n):
            board[x][y] = random.randint(1,n)*random.choice([-1,1])

    return board

def solve_puzzle(puzzle):
    """Solves the puzzle using backtracking"""
    n = len(puzzle)
    sol = [[0 for i in range(n)] for j in range(n)]
    if (solve_helper(puzzle, 0, 0, sol, n)):
        return sol
    else:
        return False

def solve_helper(puzzle, x, y, sol, n):
    """Helper function for solve_puzzle"""
    if x == n-1 and y == n:
        return True    

    for num in range(1,n+1):
        if is_valid(puzzle, x, y, num, n):
            sol[x][y] = num

            if y < n-1:
                if solve_helper(puzzle, x, y+1, sol, n):
                    return True
            else:
                if solve_helper(puzzle, x+1, 0, sol, n):
                    return True

    return False


def is_valid(puzzle, x, y, num, n):
    """Checks if a number can be placed at a valid cell"""
    # Check row
    for i in range(n):
        if num == puzzle[x][i]:
            return False
    # Check column
    for i in range(n):
        if num == puzzle[i][y]:
            return False
    return True

