class HashTable:
    def __init__(self, size):
        self.size = size
        self.table = [[] for _ in range(size)]

    def _hash(self, key):
        # Hash function implementation (can vary based on requirements)
        return hash(key) % self.size

    def add(self, key, value):
        hash_value = self._hash(key)
        key_value_pair = (key, value)
        if key_value_pair not in self.table[hash_value]:
            self.table[hash_value].append(key_value_pair)

    def get(self, key):
        hash_value = self._hash(key)
        for key_value_pair in self.table[hash_value]:
            if key_value_pair[0] == key:
                return key_value_pair[1]
        return None

