class Vector:

    def __init__(self, vector):
        self.vector = vector

    def add(self, other):
        if len(self.vector) != len(other.vector):
            raise Exception("Vectors must have equal length")
        sum_vector = []
        for i in range(len(self.vector)):
            sum_vector.append(self.vector[i] + other.vector[i])
        return Vector(sum_vector)

    def dot(self, other):
        if len(self.vector) != len(other.vector):
            raise Exception("Vectors must have equal length")
        dot_product = 0
        for i in range(len(self.vector)):
            dot_product += self.vector[i] * other.vector[i]
        return dot_product

