import random

def generate_maze(width, height, depth):
    maze = [[[0 for k in range(depth)] for j in range(height)] for i in range(width)]

    # Generate random paths by randomly changing the value of grid elements 
    for k in range(depth):
        for j in range(height):
            for i in range(width):
                if random.randint(0, 20) == 1:
                    maze[i][j][k] = 1

    # Remove loops in the maze
    for k in range(depth):
        for j in range(height):
            for i in range(width):
                if maze[i][j][k] == 1:
                    if i-1 >= 0:   
                        maze[i-1][j][k] = 0
                    if i+1 < width: 
                        maze[i+1][j][k] = 0
                    if j-1 >= 0:   
                        maze[i][j-1][k] = 0
                    if j+1 < height: 
                        maze[i][j+1][k] = 0
                    if k-1 >= 0:   
                        maze[i][j][k-1] = 0 
                    if k+1 < depth: 
                        maze[i][j][k+1] = 0

    # Generate the start and end locations
    while True:
        start_i, start_j, start_k = random.randint(0, width-1), random.randint(0, height-1), random.randint(0, depth-1)
        if maze[start_i][start_j][start_k] == 0:
            break

    while True:
        end_i, end_j, end_k = random.randint(0, width-1), random.randint(0, height-1), random.randint(0, depth-1)
        if maze[end_i][end_j][end_k] == 0 and (start_i, start_j, start_k) != (end_i, end_j, end_k):
            break

    return maze, (start_i, start_j, start_k), (end_i, end_j, end_k)

