            4: 'forty',
            5: 'fifty',
            6: 'sixty',
            7: 'seventy',
            8: 'eighty',
            9: 'ninety'
        }
        return switcher.get(num)

    def two(num):
        if not num:
            return ''
        elif num < 10:
            return one(num)
        elif num < 20:
            return two_less_20(num)
        else:
            tens, remainder = divmod(num, 10)
            return ten(tens) + '-' + one(remainder) if remainder else ten(tens)

    def three(num):
        hundred, remainder = divmod(num, 100)
        return one(hundred) + ' hundred' + ' and ' + two(remainder) if hundred and remainder else one(hundred) + ' hundred' if hundred else two(remainder)

    billion, remainder = divmod(n, 10**9)
    million, remainder = divmod(remainder, 10**6)
    thousand, remainder = divmod(remainder, 10**3)
    result = ''
