def optimize_equations(equations):
    # Get the dimension of the system
    n = len(equations)

    # Initialize the coefficients matrix 
    A = [[0 for _ in range(n)] for _ in range(n)] 

    # Construct the matrix 
    for i in range(n): 
        for j in range(n + 1): 
            A[i][j] = equations[i][j]

    # Use Gaussian Elimination to convert the system of equations into an upper triangular matrix   
    for row in range(n): 
        max = 0 
        for column in range(row, n): 
            if abs(A[column][row]) > max: 
                max = abs(A[column][row]) 
                index = column 
        if abs(max) < 1e-10:
            return None

        for j in range(row, n + 1): 
            temp = A[index][j] 
            A[index][j] = A[row][j] 
            A[row][j] = temp 

        for i in range(row + 1, n): 
            temp = A[i][row] 
            for j in range(row, n + 1):
                A[i][j] = (A[i][j] - A[row][j] * temp)/A[row][row]

    # Iterate backwards through the matrix and solve for each variable
    x = [0 for _ in range(n)] 
    for i in range(n - 1, -1, -1): 
        s = 0
        for j in range(i + 1, n): 
            s = s + x[j] * A[i][j]
        x[i] = (A[i][n] - s) / A[i][i]

    # Return the optimized values in a list
    return x

EOF
