def num_subsets(arr):
    if len(arr) == 0 or len(arr) == 1:
        return 1

    cache = [[-1 for _ in range(len(arr))] for _ in range(len(arr))]

    def helper(start, end):
        if cache[start][end] != -1:
            return cache[start][end]

        if start == end:
            result = 1
        else:
            result = helper(start + 1, end) + helper(start, end - 1)

        cache[start][end] = result

        return result

    return helper(0, len(arr) - 1)

